var n=`0621-lablabi`;var a=`world-0621`;var t=`TN`;var r=`northern-africa`;var s=4;var o=42;var l={en:`Lablabi`,ua:`Лаблабі`};var g={en:`Lablabi is a Tunisia classic prepared with chicken egg, canned chickpeas, garlic, white bread. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Лаблабі, страва кухні країни Туніс зі складниками: куряче яйце, консервований нут, часник, білий хліб. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Boil the eggs for about 10 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 10 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:10,i:[[`chicken-egg`,4,`pcs`]]},{en:`Cook the listed ingredients in simmering water for about 15 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 15 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:15,i:[[`canned-chickpeas`,560,`g`],[`water`,900,`ml`],[`garlic`,3,`clove`],[`ground-cumin`,6,`g`]]},{en:`Toast these ingredients over medium heat for about 7 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 7 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:7,i:[[`white-bread`,280,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`harissa`,25,`g`],[`lemon-juice`,35,`ml`],[`extra-virgin-olive-oil`,35,`ml`]]},{en:`Ladle cumin-scented chickpeas and broth onto toasted bread, then top with peeled boiled eggs, parsley and harissa dressing.`,ua:`Покладіть нут із кминним бульйоном на підсмажений хліб, додайте очищені варені яйця, зелень і заправку з харисою.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`parsley`,22,`g`]]}];var c={slug:n,id:a,country:`TN`,region:r,servings:4,minutes:42,title:l,text:g,steps:d};export{t as country,c as default,a as id,o as minutes,r as region,s as servings,n as slug,d as steps,g as text,l as title};